	}
}

package com.dan.gimtracker;

import com.dan.gimtracker.model.TrackedEvent;
import java.lang.reflect.Proxy;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class EventTrackerTest
{
	private static final String PLAYER_NAME = "Danj Dev";
	private static final String SOURCE_CHANNEL = "GAMEMESSAGE";

	@Test
	public void levelUpEventsUseTheFirstObservedStatAsBaseline()
	{
		EventTracker tracker = new EventTracker();
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		Client client = clientWithLevels(levels, PLAYER_NAME);

		levels.put(Skill.ATTACK, 49);
		assertTrue(tracker.captureLevelUpEvents(client, statChanged(Skill.ATTACK), 50).isEmpty());

		levels.put(Skill.ATTACK, 50);
		List<TrackedEvent> events = tracker.captureLevelUpEvents(client, statChanged(Skill.ATTACK), 50);

		assertEquals(1, events.size());
		TrackedEvent event = events.get(0);
		assertEquals("LEVEL_UP", event.getType());
		assertEquals(PLAYER_NAME, event.getDetails().get("playerName"));
		assertEquals("ATTACK", event.getDetails().get("skill"));
		assertEquals(49, event.getDetails().get("oldLevel"));
		assertEquals(50, event.getDetails().get("newLevel"));
		assertEquals(1, tracker.getPendingCount());
	}

	@Test
	public void levelUpEventsIgnoreOverallSkill()
	{
		EventTracker tracker = new EventTracker();

		assertTrue(tracker.captureLevelUpEvents(clientWithLevels(new EnumMap<>(Skill.class), PLAYER_NAME), statChanged(Skill.OVERALL), 1).isEmpty());
		assertEquals(0, tracker.getPendingCount());
	}

	@Test
	public void bossKillCountEventsHonorThresholdAndReplaceTheActiveSessionEvent()
	{
		EventTracker tracker = new EventTracker();

		assertTrue(tracker.captureBossKillCountEvent(PLAYER_NAME, "Zulrah", "KILL_COUNT", 10, 3).isEmpty());
		assertTrue(tracker.captureBossKillCountEvent(PLAYER_NAME, "Zulrah", "KILL_COUNT", 11, 3).isEmpty());

		List<TrackedEvent> thresholdEvent =
			tracker.captureBossKillCountEvent(PLAYER_NAME, "Zulrah", "KILL_COUNT", 12, 3);

		assertEquals(1, thresholdEvent.size());
		assertEquals(3, thresholdEvent.get(0).getDetails().get("count"));
		assertEquals(12, thresholdEvent.get(0).getDetails().get("totalCount"));
		assertEquals(1, tracker.getPendingCount());

		List<TrackedEvent> replacementEvent =
			tracker.captureBossKillCountEvent(PLAYER_NAME, "Zulrah", "KILL_COUNT", 13, 3);

		assertEquals(1, replacementEvent.size());
		assertEquals(4, replacementEvent.get(0).getDetails().get("count"));
		assertEquals(13, replacementEvent.get(0).getDetails().get("totalCount"));
		assertEquals(1, tracker.getPendingCount());
		assertEquals(4, tracker.drainPendingEvents().get(0).getDetails().get("count"));
	}

	@Test
	public void bossDropEventsHonorThresholdAndReplaceDuplicateDrops()
	{
		EventTracker tracker = new EventTracker();

		assertTrue(tracker.captureBossDropEvent("Vorkath", "Draconic visage", 49999, PLAYER_NAME, SOURCE_CHANNEL, 50000).isEmpty());

		List<TrackedEvent> firstDrop =
			tracker.captureBossDropEvent("Vorkath", "Draconic visage", 50000, PLAYER_NAME, SOURCE_CHANNEL, 50000);
		List<TrackedEvent> duplicateDrop =
			tracker.captureBossDropEvent("Vorkath", "Draconic visage", 50000, PLAYER_NAME, SOURCE_CHANNEL, 50000);

		assertEquals(1, firstDrop.size());
		assertEquals(1, duplicateDrop.size());
		assertEquals(1, tracker.getPendingCount());
		assertEquals("BOSS_DROP", tracker.drainPendingEvents().get(0).getType());
	}

	@Test
	public void completionStyleEventsAreOnlyQueuedOncePerSessionKey()
	{
		EventTracker tracker = new EventTracker();

		assertOneEvent("COMBAT_TASK_COMPLETE",
			tracker.captureCombatTaskEvent(PLAYER_NAME, "Perfect Theatre", "GRANDMASTER", SOURCE_CHANNEL));
		assertTrue(tracker.captureCombatTaskEvent(PLAYER_NAME, "Perfect Theatre", "GRANDMASTER", SOURCE_CHANNEL).isEmpty());

		assertOneEvent("QUEST_COMPLETE",
			tracker.captureQuestEvent(PLAYER_NAME, "Dragon Slayer II", SOURCE_CHANNEL));
		assertTrue(tracker.captureQuestEvent(PLAYER_NAME, "Dragon Slayer II", SOURCE_CHANNEL).isEmpty());

		assertOneEvent("ACHIEVEMENT_DIARY_COMPLETE",
			tracker.captureAchievementDiaryEvent(PLAYER_NAME, "Karamja", "HARD", SOURCE_CHANNEL));
		assertTrue(tracker.captureAchievementDiaryEvent(PLAYER_NAME, "Karamja", "HARD", SOURCE_CHANNEL).isEmpty());

		assertOneEvent("COLLECTION_LOG",
			tracker.captureCollectionLogEvent(PLAYER_NAME, "Abyssal orphan", 1, 12, SOURCE_CHANNEL));
		assertTrue(tracker.captureCollectionLogEvent(PLAYER_NAME, "Abyssal orphan", 1, 12, SOURCE_CHANNEL).isEmpty());

		assertEquals(4, tracker.getPendingCount());
	}

	private static void assertOneEvent(String expectedType, List<TrackedEvent> events)
	{
		assertEquals(1, events.size());
		assertEquals(expectedType, events.get(0).getType());
	}

	private static StatChanged statChanged(Skill skill)
	{
		return new StatChanged(skill, 0, 0, 0);
	}

	private static Client clientWithLevels(Map<Skill, Integer> levels, String playerName)
	{
		Player player = playerNamed(playerName);
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[] {Client.class},
			(proxy, method, args) ->
			{
				if ("getRealSkillLevel".equals(method.getName()))
				{
					return levels.getOrDefault((Skill) args[0], 1);
				}
				if ("getLocalPlayer".equals(method.getName()))
				{
					return player;
				}

				return defaultValue(proxy, method, args);
			}
		);
	}

	private static Player playerNamed(String playerName)
	{
		return (Player) Proxy.newProxyInstance(
			Player.class.getClassLoader(),
			new Class<?>[] {Player.class},
			(proxy, method, args) ->
			{
				if ("getName".equals(method.getName()))
				{
					return playerName;
				}

				return defaultValue(proxy, method, args);
			}
		);
	}

	private static Object defaultValue(Object proxy, java.lang.reflect.Method method, Object[] args)
	{
		if ("toString".equals(method.getName()))
		{
			return proxy.getClass().getInterfaces()[0].getSimpleName() + "Stub";
		}
		if ("hashCode".equals(method.getName()))
		{
			return System.identityHashCode(proxy);
		}
		if ("equals".equals(method.getName()))
		{
			return proxy == args[0];
		}

		Class<?> returnType = method.getReturnType();
		if (returnType == Void.TYPE)
		{
			return null;
		}
		if (returnType == Boolean.TYPE)
		{
			return false;
		}
		if (returnType == Byte.TYPE)
		{
			return (byte) 0;
		}
		if (returnType == Short.TYPE)
		{
			return (short) 0;
		}
		if (returnType == Integer.TYPE)
		{
			return 0;
		}
		if (returnType == Long.TYPE)
		{
			return 0L;
		}
		if (returnType == Float.TYPE)
		{
			return 0f;
		}
		if (returnType == Double.TYPE)
		{
			return 0d;
		}
		if (returnType == Character.TYPE)
		{
			return (char) 0;
		}
		return null;
	}
}

package com.dan.gimtracker;

import com.dan.gimtracker.model.TrackedEvent;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

public class EventTracker
{
	private static final int MAX_RECENT_EVENTS = 20;

	private final Map<Skill, Integer> lastKnownLevels = new EnumMap<>(Skill.class);
	private final Map<String, Integer> lastReportedBossCounts = new HashMap<>();
	private final Map<String, Integer> sessionBossCounts = new HashMap<>();
	private final Set<String> completedCombatTasks = new HashSet<>();
	private final Set<String> unlockedCollectionLogEntries = new HashSet<>();
	private final Set<String> questsCompleted = new HashSet<>();
	private final Set<String> completedAchievementDiaries = new HashSet<>();
	private final List<TrackedEvent> pendingEvents = new ArrayList<>();
	private final Deque<TrackedEvent> recentEvents = new ArrayDeque<>();
	private String currentBossSessionId = Instant.now().toString();

	// Clears login state so the next observed stats are treated as the baseline, not as fresh level-ups.
	public void resetLevelBaseline()
	{
		lastKnownLevels.clear();
	}

	// Clears remembered boss counts so a fresh session can establish its own event baseline.
	public void resetBossCountBaseline()
	{
		lastReportedBossCounts.clear();
		sessionBossCounts.clear();
		currentBossSessionId = Instant.now().toString();
	}

	// Clears remembered combat tasks so a fresh session can establish which completions are new.
	public void resetCombatTaskBaseline()
	{
		completedCombatTasks.clear();
	}

	// Clears remembered collection-log items so a fresh session can establish which unlocks are new.
	public void resetCollectionLogBaseline()
	{
		unlockedCollectionLogEntries.clear();
	}

	public void resetQuestsCompleted()
	{
		questsCompleted.clear();
	}

	public void resetAchievementDiariesCompleted()
	{
		completedAchievementDiaries.clear();
	}

	// Converts a RuneLite stat change into one or more queued level-up events when the real level increases.
	public List<TrackedEvent> captureLevelUpEvents(Client client, StatChanged event, int threshold)
	{
		Skill skill = event.getSkill();
		if (skill == Skill.OVERALL)
		{
			return List.of();
		}

		int currentLevel = client.getRealSkillLevel(skill);
		Integer previousLevel = lastKnownLevels.put(skill, currentLevel);

		if (previousLevel == null)
		{
			return List.of();
		}

		if (currentLevel <= previousLevel)
		{
			return List.of();
		}

		if (currentLevel < threshold)
		{
			return List.of();
		}

		String playerName = client.getLocalPlayer() == null ? "Unknown" : client.getLocalPlayer().getName();
		TrackedEvent trackedEvent = TrackedEvent.levelUp(playerName, skill.name(), previousLevel, currentLevel);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}

	// Queues boss KC events once they pass the configured threshold and the count has advanced.
	public List<TrackedEvent> captureBossKillCountEvent(String playerName, String bossName, String countType, int count, int threshold)
	{
		if (threshold <= 0)
		{
			return List.of();
		}

		String bossKey = bossName + "|" + countType;
		Integer previousCount = lastReportedBossCounts.get(bossKey);
		if (previousCount == null)
		{
			lastReportedBossCounts.put(bossKey, count);
			if (sessionBossCounts.containsKey(bossKey))
			{
				return List.of();
			}

			sessionBossCounts.put(bossKey, 1);
			if (threshold > 1)
			{
				return List.of();
			}
		}
		else if (count <= previousCount)
		{
			return List.of();
		}
		else
		{
			lastReportedBossCounts.put(bossKey, count);
			int increment = count - previousCount;
			sessionBossCounts.merge(bossKey, increment, Integer::sum);
		}

		int sessionCount = sessionBossCounts.getOrDefault(bossKey, 0);
		if (sessionCount < threshold)
		{
			return List.of();
		}

		TrackedEvent trackedEvent = TrackedEvent.bossKillCount(
			playerName,
			bossName,
			countType,
			sessionCount,
			count,
			currentBossSessionId
		);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}

	// Queues boss drop events once they pass the configured value threshold.
	public List<TrackedEvent> captureBossDropEvent(
		String bossName,
		String itemName,
		long value,
		String playerName,
		String sourceChannel,
		int threshold
	)
	{
		if (value < threshold)
		{
			return List.of();
		}

		TrackedEvent trackedEvent = TrackedEvent.bossDrop(bossName, itemName, value, playerName, sourceChannel);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}

	// Queues a combat task completion the first time that task is observed in the current session.
	public List<TrackedEvent> captureCombatTaskEvent(String playerName, String taskName, String tier, String sourceChannel)
	{
		String normalizedTask = taskName.trim();
		String normalizedTier = tier == null ? "" : tier.trim().toUpperCase();
		String taskKey = normalizedTier + "|" + normalizedTask;
		if (!completedCombatTasks.add(taskKey))
		{
			return List.of();
		}

		TrackedEvent trackedEvent = TrackedEvent.combatTaskComplete(playerName, normalizedTask, normalizedTier, sourceChannel);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}
	public List<TrackedEvent> captureQuestEvent(String playerName, String questName, String sourceChannel)
	{
		String key = playerName.trim() + "|" + questName.trim();
		if(!questsCompleted.add(key)){
			return List.of();
		}
		TrackedEvent trackedEvent = TrackedEvent.questCompleted(playerName, questName, sourceChannel);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}

	public List<TrackedEvent> captureAchievementDiaryEvent(String playerName, String regionName, String tier, String sourceChannel)
	{
		String normalizedRegion = regionName.trim();
		String normalizedTier = tier.trim().toUpperCase();
		String key = playerName.trim() + "|" + normalizedTier + "|" + normalizedRegion;
		if (!completedAchievementDiaries.add(key))
		{
			return List.of();
		}

		TrackedEvent trackedEvent = TrackedEvent.achievementDiaryCompleted(
			playerName,
			normalizedRegion,
			normalizedTier,
			sourceChannel
		);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}

	// Queues a collection-log item the first time that item/count combination is observed in the session.
	public List<TrackedEvent> captureCollectionLogEvent(
		String playerName,
		String itemName,
		int unlockedCount,
		int totalCount,
		String sourceChannel
	)
	{
		String key = playerName.trim() + "|" + itemName.trim() + "|" + unlockedCount + "|" + totalCount;
		if (!unlockedCollectionLogEntries.add(key))
		{
			return List.of();
		}

		TrackedEvent trackedEvent = TrackedEvent.collectionLogItem(
			playerName.trim(),
			itemName.trim(),
			unlockedCount,
			totalCount,
			sourceChannel
		);
		queueEvent(trackedEvent);
		return List.of(trackedEvent);
	}

	// Hands pending events to the sync layer and clears the queue on a best-effort basis.
	public List<TrackedEvent> drainPendingEvents()
	{
		List<TrackedEvent> drained = new ArrayList<>(pendingEvents);
		pendingEvents.clear();
		return drained;
	}

	// Restores failed uploads to the front of the queue so they are retried before newer events.
	public void requeue(List<TrackedEvent> events)
	{
		if (events.isEmpty())
		{
			return;
		}

		pendingEvents.addAll(0, events);
	}

	// Exposes queue depth for the sidebar and timer logic.
	public int getPendingCount()
	{
		return pendingEvents.size();
	}

	// Clears local pending and recent event state when the active group is reset or left.
	public void clearTrackedEvents()
	{
		pendingEvents.clear();
		recentEvents.clear();
	}

	// Returns the latest tracked events for quick validation in the sidebar.
	public List<TrackedEvent> getRecentEvents()
	{
		return new ArrayList<>(recentEvents);
	}

	public List<TrackedEvent> buildBossSessionSummaryEvents(String playerName)
	{
		List<TrackedEvent> summaries = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : sessionBossCounts.entrySet())
		{
			int sessionCount = entry.getValue();
			if (sessionCount <= 0)
			{
				continue;
			}

			String[] bossKeyParts = entry.getKey().split("\\|", 2);
			if (bossKeyParts.length != 2)
			{
				continue;
			}

			int totalCount = lastReportedBossCounts.getOrDefault(entry.getKey(), sessionCount);
			summaries.add(TrackedEvent.bossKillCountSession(
				playerName,
				bossKeyParts[0],
				bossKeyParts[1],
				sessionCount,
				totalCount,
				currentBossSessionId
			));
		}

		return summaries;
	}

	// Adds a new event to the pending queue and bounded recent history.
	private void queueEvent(TrackedEvent trackedEvent)
	{
		if ("BOSS_KC".equals(trackedEvent.getType()))
		{
			removeMatchingBossKcEvent(pendingEvents, trackedEvent);
			removeMatchingBossKcEvent(recentEvents, trackedEvent);
		}
		else if ("BOSS_DROP".equals(trackedEvent.getType()))
		{
			removeMatchingBossDropEvent(pendingEvents, trackedEvent);
			removeMatchingBossDropEvent(recentEvents, trackedEvent);
		}

		pendingEvents.add(trackedEvent);
		addRecentEvent(trackedEvent);
	}

	private void addRecentEvent(TrackedEvent trackedEvent)
	{
		recentEvents.addFirst(trackedEvent);
		while (recentEvents.size() > MAX_RECENT_EVENTS)
		{
			recentEvents.removeLast();
		}
	}

	private void removeMatchingBossKcEvent(Iterable<TrackedEvent> events, TrackedEvent targetEvent)
	{
		Iterator<TrackedEvent> iterator = events.iterator();
		while (iterator.hasNext())
		{
			TrackedEvent existingEvent = iterator.next();
			if (!"BOSS_KC".equals(existingEvent.getType()))
			{
				continue;
			}

			if (sameBossKcStream(existingEvent, targetEvent))
			{
				iterator.remove();
				return;
			}
		}
	}

	private boolean sameBossKcStream(TrackedEvent first, TrackedEvent second)
	{
		Map<String, Object> firstDetails = first.getDetails();
		Map<String, Object> secondDetails = second.getDetails();
		return String.valueOf(firstDetails.get("playerName")).equals(String.valueOf(secondDetails.get("playerName")))
			&& String.valueOf(firstDetails.get("bossName")).equals(String.valueOf(secondDetails.get("bossName")))
			&& String.valueOf(firstDetails.get("countType")).equals(String.valueOf(secondDetails.get("countType")));
	}

	private void removeMatchingBossDropEvent(Iterable<TrackedEvent> events, TrackedEvent targetEvent)
	{
		Iterator<TrackedEvent> iterator = events.iterator();
		while (iterator.hasNext())
		{
			TrackedEvent existingEvent = iterator.next();
			if (!"BOSS_DROP".equals(existingEvent.getType()))
			{
				continue;
			}

			if (sameBossDrop(existingEvent, targetEvent))
			{
				iterator.remove();
				return;
			}
		}
	}

	private boolean sameBossDrop(TrackedEvent first, TrackedEvent second)
	{
		Map<String, Object> firstDetails = first.getDetails();
		Map<String, Object> secondDetails = second.getDetails();
		return String.valueOf(firstDetails.get("playerName")).equals(String.valueOf(secondDetails.get("playerName")))
			&& String.valueOf(firstDetails.get("itemName")).equals(String.valueOf(secondDetails.get("itemName")))
			&& String.valueOf(firstDetails.get("value")).equals(String.valueOf(secondDetails.get("value")));
	}
}

